# Appendix Tables E.1 and E.2 (decomposition by major group, top occupations): where the decline in young workers comes from. Run from anywhere:
#   python3 code/tables/tab8-decomposition.py      (writes output/tables/tab8-1-decomposition.tex and tab8-2-top-occupations.tex)
# Inputs: the cleaned first-difference files (data/regression_inputs/cell_fd/fd_baseline_3m_occ2010_age_u30.dta and _ageedu_u30_no_ba.dta,
# the exact inputs of the Table 4 regressions for the two groups), occ2010_q_age3.dta (data/pipeline/) for occupation titles only, and the
# major-group code ranges printed in the lab's leave-one-out table (data/lab/paper_tables/). Reading the lab's files makes the coefficients
# identical to Table 4 by construction.
# The regression: the three-year difference in the log count of young workers, 2026Q1 vs 2023Q1 and 2026Q2 vs 2023Q2 stacked
# with a period effect, the twelve full-occupation base-period composition shares, base-period young employment weights,
# exposure standardized across the 451 scored occupations, standard errors clustered by occupation.
# Table E.1: Frisch-Waugh decomposition of the coefficient. After partialling the controls and the period effect out of the
# standardized exposure change (z) and the outcome (dy) with the regression weights, the coefficient equals
# sum_i w_i r_z,i r_y,i / sum_i w_i r_z,i^2, and each occupation's term is its contribution; the table sums them by major group.
# Table E.2 (tab:topoccs): the occupations in the most exposed quartile with the largest employment-weighted declines in young workers,
# i.e., base-period count times log change, as a share of the quartile's net loss; occupations with fewer than 50,000
# weighted young workers (monthly average) in the base period are excluded from the ranking (the share is still of the full quartile).
import sys as _sys, pathlib as _pl; _sys.path.insert(0, str(_pl.Path(__file__).resolve().parents[1])); from paths import *   # repository-relative paths (code/paths.py)
import re, datetime, numpy as np, pandas as pd, statsmodels.api as sm, warnings
warnings.filterwarnings("ignore")
G=str(CELL_FD)+"/"; D=str(PIPELINE)+"/"   # data/cell_fd/ and data/pipeline/
today=datetime.date.today().strftime("%B %-d, %Y")
_mg=pd.read_csv(CROSSWALKS/"occ2010_major_groups.csv")   # the 22 major groups of the 2010 census classification, with their code ranges
groups=[(int(r.mgroup),r["name"],int(r.occ2010_low),int(r.occ2010_high)) for _,r in _mg.iterrows()]
NAMES={}
def grp(code):
    for n,name,a,b in groups:
        if a<=code<=b: return NAMES.get(name,name)
    return "Unmapped"
ctrl=["base_share_female","base_share_under30","base_share_age50plus","base_share_white","base_share_black","base_share_asian","base_share_hs_less","base_share_ba","base_share_postba","base_share_south","base_share_midwest","base_share_northeast"]
titles=next(iter(pd.read_stata(D+"occ2010_q_age3.dta", iterator=True).value_labels().values()))

def build(fname):
    t=pd.read_stata(G+fname, convert_categoricals=False, convert_dates=False)
    df=t[(t.horizon_years==3)&t.later_period.isin([264,265])&(t.base_emp>0)].dropna(subset=["d_log_emp","z_d_s4_s1","base_emp"]+ctrl).copy()
    df=df.rename(columns={"z_d_s4_s1":"z","base_emp":"w"}); df["dy"]=100*df.d_log_emp; df["later"]=(df.later_period==265).astype(int); df["d_ens_s4_s1"]=df.d_s4_s1
    X=sm.add_constant(df[["z"]+ctrl+["later"]])
    fit=sm.WLS(df.dy,X,weights=df.w).fit(cov_type="cluster",cov_kwds={"groups":df.occ2010})
    W=df.w.values; Xc=sm.add_constant(df[ctrl+["later"]])
    rz=sm.WLS(df.z,Xc,weights=W).fit().resid.values; ry=sm.WLS(df.dy,Xc,weights=W).fit().resid.values
    df["contrib"]=W*rz*ry/(W*rz*rz).sum()
    df["group"]=df.occ2010.apply(grp); df["title"]=df.occ2010.map(titles)
    return df, fit.params["z"], fit.bse["z"], len(df), df.occ2010.nunique()

samples={"Under 30":build("fd_baseline_3m_occ2010_age_u30.dta"), "Under 30, less than a bachelor's degree":build("fd_baseline_3m_occ2010_ageedu_u30_no_ba.dta")}

# ---------------- Table 8.1: contributions by major group
G={}
for k,(df,b,se,n,nocc) in samples.items():
    g=df.groupby("group").agg(contrib=("contrib","sum"), emp=("w","sum"), dE=("d_ens_s4_s1","mean"))
    g["share"]=100*g.contrib/df.contrib.sum(); g["emp"]=100*g.emp/df.w.sum(); G[k]=g
order=G["Under 30"].sort_values("contrib").index
def f(x,d=2):
    x=round(float(x),d); x=0.0 if x==0 else x
    return f"{x:.{d}f}".replace("-","$-$")
L=[]
L.append("% Appendix Table E.1: contributions to the young-worker coefficient by major occupation group.")
L.append("% Generated by code/tables/tab8-decomposition.py from the cleaned first-difference files. Do not edit by hand.")
L.append("\\begin{table}[htbp]\n\\centering\n\\begin{threeparttable}")
L.append("\\caption{Where the decline in young workers comes from: contributions to the coefficient by major occupation group}")
L.append("\\label{tab:decomposition}")
L.append("\\footnotesize\\setlength{\\tabcolsep}{2pt}\n\\begin{spacing}{1}\\scriptsize")
L.append("\\begin{tabular}{@{}l*{7}{r}@{}}\n\\toprule")  # three-line headers and a 3pt column gap, so the table fits the text width without wrapping the group names
L.append(" & & \\multicolumn{3}{c}{Workers under 30} & \\multicolumn{3}{c}{Under 30, less than a bachelor's degree} \\\\")
L.append("\\cmidrule(lr){3-5}\\cmidrule(lr){6-8}")
L.append("Major occupation group & \\shortstack[r]{Mean\\\\exposure\\\\change} & \\shortstack[r]{Contribution\\\\(log\\\\points)} & \\shortstack[r]{Share of\\\\coefficient\\\\(\\%)} & \\shortstack[r]{Share of\\\\young\\\\employment (\\%)} & \\shortstack[r]{Contribution\\\\(log\\\\points)} & \\shortstack[r]{Share of\\\\coefficient\\\\(\\%)} & \\shortstack[r]{Share of\\\\young\\\\employment (\\%)} \\\\")
L.append("\\midrule")
for grpname in order:
    a=G["Under 30"].loc[grpname]; c=G["Under 30, less than a bachelor's degree"].loc[grpname] if grpname in G["Under 30, less than a bachelor's degree"].index else None
    row=[grpname, f(a.dE,1), f(a.contrib), f(a.share,1), f(a.emp,1)]
    row+= [f(c.contrib), f(c.share,1), f(c.emp,1)] if c is not None else ["","",""]
    L.append(" & ".join(row)+" \\\\")
L.append("\\midrule")
bU,seU,nU,oU=samples["Under 30"][1:]; bN,seN,nN,oN=samples["Under 30, less than a bachelor's degree"][1:]
L.append(f"Coefficient (sum of contributions) & & {f(bU)} & 100.0 & 100.0 & {f(bN)} & 100.0 & 100.0 \\\\")
L.append(f"Standard error & & ({seU:.2f}) & & & ({seN:.2f}) & & \\\\")
L.append(f"Occupation-windows [occupations] & & {nU} [{oU}] & & & {nN} [{oN}] & & \\\\")
L.append("\\bottomrule\n\\end{tabular}\n\\end{spacing}")
L.append("\\begin{tablenotes}\\notesize")
L.append("\\item Notes: The coefficient is the three-year first difference of Eq.~(\\ref{eq:group}) of the paper for the log count of young workers, 2026Q1 vs.\\ 2023Q1 and 2026Q2 vs.\\ 2023Q2 stacked, with the twelve base-period composition controls, base-period young employment weights, and standard errors clustered by occupation, i.e., the under-30 row of Table~\\ref{tab:cell_fd_main_4} of the paper and the young non-graduate cell of Table~\\ref{tab:cell_fd_main_5}, decomposed in Figures~\\ref{fig:decomposition} and~\\ref{fig:decompgroups} of the paper. After the controls and the period effect are partialled out, the coefficient equals the weighted sum over occupations of the product of the exposure-change deviation and the outcome deviation, divided by the weighted sum of squared exposure-change deviations, and each occupation's term is its contribution. Rows sum the contributions within the 22 major census occupation groups. A negative contribution comes from occupations with above-average exposure change whose young employment fell relative to prediction, or from occupations with below-average exposure change whose young employment rose relative to prediction. Mean exposure change is the unweighted mean of the stage-1 to stage-4 change across the group's occupations; share of young employment is the group's share of the base-period weights.")
L.append("\\end{tablenotes}\n\\end{threeparttable}\n\\end{table}")
open(TABLES/"tab8-1-decomposition.tex","w").write("\n".join(L)+"\n")

# ---------------- Table 8.2: top-quartile occupations with the largest declines
MIN=50000   # monthly-average weighted young workers in the base period
P=[]
P.append("% Appendix table (Appendix E): occupations in the most exposed quartile with the largest declines in young workers.")
P.append("% Generated by code/tables/tab8-decomposition.py from the cleaned first-difference files. Do not edit by hand.")
P.append("\\begin{table}[htbp]\n\\centering\n\\begin{threeparttable}")
P.append("\\caption{Occupations in the most exposed quartile with the largest declines in young workers, 2023H1 to 2026H1}")
P.append("\\label{tab:topoccs}")
P.append("\\footnotesize\\setlength{\\tabcolsep}{4pt}\n\\begin{spacing}{1}\\scriptsize")
P.append("\\begin{tabular}{@{}lrrrr@{}}\n\\toprule")
P.append("Occupation & \\shortstack[r]{Exposure\\\\change} & \\shortstack[r]{Young workers\\\\in 2023H1 (thousands)} & \\shortstack[r]{Change in log\\\\count (log points)} & \\shortstack[r]{Share of the quartile's\\\\net loss (\\%)} \\\\")
P.append("\\midrule")
summ={}
for k,(df,b,se,n,nocc) in samples.items():
    q=df.groupby("occ2010").agg(dE=("d_ens_s4_s1","first"), dy=("dy","mean"), w=("w","sum"), title=("title","first"), group=("group","first")).reset_index()
    q["w"]=q.w/2  # two windows stacked; base_emp is already the monthly-average base count
    q["quart"]=pd.qcut(q.dE.rank(method="first"),4,labels=[1,2,3,4]).astype(int)
    top=q[q.quart==4].copy(); netloss=(top.w*top.dy).sum(); top["share"]=100*(top.w*top.dy)/netloss
    summ[k]=dict(n_pass=int((top.w>=MIN).sum()), top_mean=np.average(top.dy,weights=top.w), bot_mean=np.average(q[q.quart==1].dy,weights=q[q.quart==1].w), n_top=len(top), n_small=(top.w<MIN).sum(), netloss=netloss/1000)
    P.append(f"\\multicolumn{{5}}{{@{{}}l}}{{\\textit{{{k}}}}} \\\\")
    for _,r in top[(top.w>=MIN)&(top.dy<0)].sort_values("share",ascending=False).head(10).iterrows():
        t=r.title[0].upper()+r.title[1:]; t=t.split(", including")[0]
        P.append(f"{t} & {r.dE:.0f} & {r.w/1000:,.0f} & {f(r.dy,0)} & {r.share:.1f} \\\\")
    P.append("\\addlinespace")
P.append("\\bottomrule\n\\end{tabular}\n\\end{spacing}")
u=summ["Under 30"]; v=summ["Under 30, less than a bachelor's degree"]
P.append("\\begin{tablenotes}\\notesize")
P.append(f"\\item Notes: Occupations are ranked by their employment-weighted decline in young workers, i.e., the base-period count times the change in the log count between the first half of 2023 and the first half of 2026 (the average of the 2026Q1 vs.\\ 2023Q1 and 2026Q2 vs.\\ 2023Q2 differences), as a share of the net loss across all occupations in the most exposed quartile of the stage-1 to stage-4 change. Shares are raw changes, not deviations from a mean, and do not use the composition controls. Occupations with fewer than {MIN//1000:,} weighted young workers in the base period (monthly average) are not ranked. The employment-weighted mean change in the log count of young workers is {f(u['top_mean'],1)} log points in the most exposed quartile and {f(u['bot_mean'],1)} in the least exposed for workers under 30, and {f(v['top_mean'],1)} and {f(v['bot_mean'],1)} for young workers without a bachelor's degree. Counts are CPS weighted counts of employed workers, monthly averages.")
P.append("\\end{tablenotes}\n\\end{threeparttable}\n\\end{table}")
open(TABLES/"tab8-2-top-occupations.tex","w").write("\n".join(P)+"\n")
print("under 30: %.2f (%.2f) n=%d; non-grad: %.2f (%.2f) n=%d" % (bU,seU,nU,bN,seN,nN))
print({k:{kk:round(float(vv),2) for kk,vv in d.items()} for k,d in summ.items()})
